1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {ListSessionsMessage, OutgoingMessage, SessionSummaryFrame} from '../../types/messages.js';
6	import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
22	import {log} from '../../shared/logger.js';
23	
24	interface StreamState {
25	  thinkingIndex: number | null;
26	  assistantIndex: number | null;
27	  suppressOutput: boolean;
28	  sentAssistantIndices: number[];
29	}
30	
31	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
32	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
33	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
34	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
35	  const lock = new PerSessionLock();
36	  return function handleMessage(
37	    ws: WebSocket,
38	    session: ChatSession,
39	    rawMessage: unknown,
40	    signal?: AbortSignal
41	  ): Promise<void> {
42	    const validation = validateMessage(rawMessage);
43	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
44	    if (isUserMessageFrame(rawMessage)) {
45	      return lock.run(session.sessionId, () =>
46	        answerInTurn(ws, session, orchestrator, validation, signal, sessionStore)
47	      );
48	    }
49	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
50	    return wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore));
51	  };
52	}
53	
54	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
55	async function answerInTurn(
56	  ws: WebSocket,
57	  session: ChatSession,
58	  orchestrator: ChatOrchestrator,
59	  validation: ValidationResult,
60	  signal: AbortSignal | undefined,
61	  sessionStore: SessionStore | undefined
62	): Promise<void> {
63	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
64	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
65	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
66	    return;
67	  }
68	  const startedAt = Date.now();
69	  try {
70	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal, sessionStore));
71	  } finally {
72	    endTurn(ws, session, signal, startedAt);
73	  }
74	}
75	
76	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
77	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
78	  if (signal?.aborted) {
79	    log.info('message', 'turn abandoned: its socket closed', {
80	      sessionId: session.sessionId,
81	      elapsedMs: Date.now() - startedAt,
82	    });
83	    return;
84	  }
85	  sendStreamEnd(ws);
86	}
87	
88	async function answerUserMessage(
89	  ws: WebSocket,
90	  session: ChatSession,
91	  orchestrator: ChatOrchestrator,
92	  validation: ValidationResult,
93	  signal: AbortSignal | undefined,
94	  sessionStore: SessionStore | undefined
95	): Promise<void> {
96	  const message = validation.valid ? validation.data : undefined;
97	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
98	  await answerFrame(ws, session, validation, sessionStore);
99	}
100	
101	async function answerFrame(
102	  ws: WebSocket,
103	  session: ChatSession,
104	  validation: ValidationResult,
105	  sessionStore: SessionStore | undefined
106	): Promise<void> {
107	  if (!validation.valid) {
108	    log.warn('message', 'validation failed', {error: validation.error});
109	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
110	    return;
111	  }
112	
113	  const message = validation.data;
114	  if (message.type === 'ping') handlePing(ws, message.timestamp);
115	  if (message.type === 'list_sessions') await handleListSessions(ws, session, sessionStore, message);
116	}
117	
118	// Read beside the lock: a history request is not a turn and must not queue behind a streaming answer.
119	async function handleListSessions(
120	  ws: WebSocket,
121	  session: ChatSession,
122	  sessionStore: SessionStore | undefined,
123	  message: ListSessionsMessage
124	): Promise<void> {
125	  try {
126	    const summaries =
127	      (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
128	    sendJson(ws, {type: 'session_list', sessions: summaries.map(toSummaryFrame)});
129	  } catch (error) {
130	    // No store detail reaches the frame or the log beyond the message: both leave the process.
131	    const detail = error instanceof Error ? error.message : 'Unknown error';
132	    log.error('ws', 'listing conversations failed', {
133	      sessionId: session.sessionId,
134	      userId: session.userId,
135	      error: detail,
136	    });
137	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
138	  }
139	}
140	
141	// A store may hand back a summary that went through JSON, so any shape a Date reads is serialised.
142	function toSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
143	  return {
144	    sessionId: summary.sessionId,
145	    createdAt: toIso(summary.createdAt),
146	    updatedAt: toIso(summary.updatedAt),
147	    entryCount: summary.entryCount,
148	  };
149	}
150	
151	function toIso(value: Date): string {
152	  return new Date(value).toISOString();
153	}
154	
155	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
156	function isUserMessageFrame(rawMessage: unknown): boolean {
157	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
158	}
159	
160	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
161	  try {
162	    await action();
163	  } catch (error) {
164	    const message = error instanceof Error ? error.message : 'Unknown error';
165	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
166	    log.error('message', 'handling error', {error: message, code});
167	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
168	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
169	      return;
170	    }
171	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
172	  }
173	}
174	
175	async function handleUserMessage(
176	  ws: WebSocket,
177	  session: ChatSession,
178	  orchestrator: ChatOrchestrator,
179	  content: string,
180	  signal: AbortSignal | undefined
181	): Promise<void> {
182	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
183	
184	  const userEntry = createUserEntry(content);
185	  const userIndex = appendEntry(session, userEntry);
186	  sendUpsert(ws, userIndex, userEntry);
187	
188	  const parser = new ThinkingTagParser();
189	  const state: StreamState = {
190	    thinkingIndex: null,
191	    assistantIndex: null,
192	    suppressOutput: false,
193	    sentAssistantIndices: [],
194	  };
195	
196	  let textChunkCount = 0;
197	
198	  try {
199	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
200	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
201	      if (signal?.aborted) break;
202	      textChunkCount = logChunk(chunk, textChunkCount);
203	      processChunk(ws, session, state, parser, chunk);
204	    }
205	  } finally {
206	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
207	    flushHeldText(ws, session, state, parser);
208	    closeCutOff(ws, session, state, 'thinkingIndex');
209	    closeCutOff(ws, session, state, 'assistantIndex');
210	  }
211	
212	  if (textChunkCount > 0) {
213	    log.debug('stream', `received ${textChunkCount} text chunks`);
214	  }
215	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
216	}
217	
218	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
219	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
220	  if (chunk.type === 'text') return textChunkCount + 1;
221	
222	  if (textChunkCount > 0) {
223	    log.debug('stream', `received ${textChunkCount} text chunks`);
224	  }
225	
226	  if (chunk.type === 'tool_result') {
227	    log.debug('stream', 'tool_result chunk', {
228	      messageCount: chunk.clientMessages.length,
229	      types: chunk.clientMessages.map(m => m.type),
230	    });
231	    return 0;
232	  }
233	
234	  log.debug('stream', 'chunk', {type: chunk.type});
235	  return 0;
236	}
237	
238	function processChunk(
239	  ws: WebSocket,
240	  session: ChatSession,
241	  state: StreamState,
242	  parser: ThinkingTagParser,
243	  chunk: MessageChunk
244	): void {
245	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
246	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
247	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
248	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
249	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
250	}
251	
252	function processTextChunk(
253	  ws: WebSocket,
254	  session: ChatSession,
255	  state: StreamState,
256	  parser: ThinkingTagParser,
257	  text: string
258	): void {
259	  const segments = parser.push(text);
260	  for (const segment of segments) {
261	    handleTextSegment(ws, session, state, segment);
262	  }
263	}
264	
265	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
266	  if (segment.type === 'thinking') {
267	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
268	    return;
269	  }
270	  commitAndClear(ws, session, state, 'thinkingIndex');
271	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
272	}
273	
274	function streamSegment(
275	  ws: WebSocket,
276	  session: ChatSession,
277	  state: StreamState,
278	  key: StateIndexKey,
279	  createEntry: EntryFactory,
280	  content: string
281	): void {
282	  const isNew = initSegment(session, state, key, createEntry);
283	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
284	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
285	  appendDelta(session, state[key]!, content);
286	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
287	}
288	
289	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
290	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
291	  markSuppressed(session, index);
292	  sendSkip(ws, index);
293	}
294	
295	function markSuppressed(session: ChatSession, index: number): void {
296	  const entry = session.entries[index];
297	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
298	}
299	
300	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
301	  if (state[key] !== null) return false;
302	  state[key] = appendEntry(session, createEntry());
303	  return true;
304	}
305	
306	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
307	  const index = state[key];
308	  if (index === null) return;
309	
310	  commitEntry(session, index);
311	  state[key] = null;
312	
313	  // Only what the client received can be retracted, and only assistant entries.
314	  if (state.suppressOutput) return;
315	
316	  sendCommit(ws, index);
317	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
318	}
319	
320	function processToolUseChunk(
321	  ws: WebSocket,
322	  session: ChatSession,
323	  toolCall: {name: string; input: Record<string, unknown>}
324	): void {
325	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
326	  const toolIndex = appendEntry(session, toolEntry);
327	  sendUpsert(ws, toolIndex, toolEntry);
328	}
329	
330	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
331	  for (const msg of clientMessages) {
332	    log.debug('stream', 'forwarding client message to frontend', {
333	      type: msg.type,
334	      index: 'index' in msg ? msg.index : undefined,
335	    });
336	    sendJson(ws, msg);
337	  }
338	}
339	
340	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
341	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
342	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
343	  commitOpenEntries(ws, session, state);
344	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
345	
346	  for (const idx of state.sentAssistantIndices) {
347	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
348	    markSuppressed(session, idx);
349	  }
350	
351	  state.sentAssistantIndices = [];
352	  state.suppressOutput = true;
353	}
354	
355	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
356	  flushHeldText(ws, session, state, parser);
357	  commitOpenEntries(ws, session, state);
358	}
359	
360	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
361	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
362	  for (const segment of parser.flush()) {
363	    handleTextSegment(ws, session, state, segment);
364	  }
365	}
366	
